    /**
     * Method to retrieve the Reservation via an ReservationPrimaryKey.
     * @param 	id Long
     * @return 	Reservation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Reservation handle( FindReservationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getReservationId() );
    }
    
    /**
     * Method to retrieve a collection of all Reservations
     *
     * @param	query	FindAllReservationQuery 
     * @return 	List<Reservation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Reservation> handle( FindAllReservationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindReservation,
 * but only if the id matches
 *
 * @param		entity	Reservation
 */
	protected void emitFindReservation( Reservation entity ) {
		LOGGER.info("handling emitFindReservation" );
		
	    queryUpdateEmitter.emit(FindReservationQuery.class,
	                            query -> query.getFilter().getReservationId().equals(entity.getReservationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllReservation
	 * 
	 * @param		entity	Reservation
	 */
	protected void emitFindAllReservation( Reservation entity ) {
		LOGGER.info("handling emitFindAllReservation" );
		
	    queryUpdateEmitter.emit(FindAllReservationQuery.class,
	                            query -> true,
	                            entity);
	}

